style.mushroom-state-info$:
.primary {
  font-size: 24px !important;
  font-weight: 700 !important;
  line-height: 1.15 !important;
}
.secondary {
  white-space: normal !important;
  overflow: visible !important;
  text-overflow: unset !important;
  line-height: 1.25 !important;
}

ha-card {
  position: relative;
  overflow: visible;
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  padding: 8px 8px 12px 82px;
  min-height: 74px;
}
ha-card::before {
  content: "🐾";
  position: absolute;
  left: 18px;
  top: 15px;
  font-size: 27px;
  filter: hue-rotate(165deg) saturate(3) brightness(1.35)
    drop-shadow(0 0 7px rgba(33,150,243,.9));
  transform-origin: center;
  animation: paw-step-left 2.2s ease-in-out infinite;
  pointer-events: none;
}
ha-card::after {
  content: "🐾";
  position: absolute;
  left: 43px;
  top: 36px;
  font-size: 24px;
  filter: hue-rotate(165deg) saturate(3) brightness(1.35)
    drop-shadow(0 0 7px rgba(33,150,243,.9));
  transform-origin: center;
  animation: paw-step-right 2.2s ease-in-out infinite;
  pointer-events: none;
}
@keyframes paw-step-left {
  0% { opacity: 0; transform: translate(-8px,5px) rotate(-18deg) scale(.8); }
  10%,34% { opacity: 1; transform: translate(0,0) rotate(-18deg) scale(1); }
  47%,100% { opacity: 0; transform: translate(8px,-5px) rotate(-18deg) scale(.85); }
}
@keyframes paw-step-right {
  0%,18% { opacity: 0; transform: translate(-8px,5px) rotate(16deg) scale(.8); }
  28%,52% { opacity: 1; transform: translate(0,0) rotate(16deg) scale(1); }
  65%,100% { opacity: 0; transform: translate(8px,-5px) rotate(16deg) scale(.85); }
}

